Algorithm ExactClosedWordCount(sigma, tau, m):
    count <- 0
    for each word w in {0,1,2,3}^m:
        g <- identity
        for i = 0 to m-1:
            g <- generators[w[i]] * g
        if g = identity:
            count <- count + 1
    return count

Complexity: Time O(4^m * m * n), Space O(n)
